Garage door state machine
class
GarageDoor
{
status {
Open {
buttonOrObstacle -> Closing;
}
Closing {
buttonOrObstacle -> Opening;
reachBottom -> Closed;
}
Closed {
buttonOrObstacle -> Opening;
}
Opening {
buttonOrObstacle -> HalfOpen;
reachTop -> Open;
}
HalfOpen {
buttonOrObstacle -> Opening;
}
