Umple for the phone line example
class
phone
{
state {
onHook {
startDialing -> dialling;
incomingCall -> ringing;
}
ringing {
pickUp -> communicating;
otherPartyHangUp -> onHook;
}
communicating {
hangUp -> onHook;
otherPartyHangUp -> waitForHook;
putOnHold -> onHold;
}
onHold {
hangUp -> onHook;
otherPartyHangUp -> waitForHook;
takeOffHold -> communicating;
}
